ELI5S_A = {
"c6_hin_cbse_01_001.md": "आसान शब्दों में: सोहनलाल द्विवेदी वे कवि हैं जिन्होंने अंग्रेज़ी राज के समय तलवार की जगह लेखनी से विरोध किया। उनका प्रिय विषय देशभक्ति था — 'बढ़े चलो, बढ़े चलो' और 'कोशिश करने वालों की हार नहीं होती' उनकी ही रचनाएँ हैं। 'ऊँचा खड़ा हिमालय' उनकी मातृभूमि-स्तुति है, इसलिए कवि को पहचानना मतलब कविता की आवाज़ को पहचानना है।",
"c6_hin_cbse_01_004.md": "आसान शब्दों में: इस कविता का नायक कोई राजा या योद्धा नहीं, स्वयं भूमि है। कवि उसे 'मातृ' कहकर मानव बना देता है और 'वह ____ भूमि मेरी' दोहराकर उसे पुकारता है, जैसे बच्चा माँ को। राम, कृष्ण और बुद्ध जैसे महापुरुष भी इसी भूमि के पुत्र कहे गए हैं — यानी भूमि उनसे भी बड़ी है।",
"c6_hin_cbse_01_005.md": "आसान शब्दों में: मातृभूमि के आसपास दो रत्न-समूह खड़े हैं। एक प्रकृति के — सिंधु, त्रिवेणी, झरने, चिड़ियाँ, घनी अमराइयाँ, कोयल और मलय पवन; दूसरे विरासत के — रघुपति-सीता, वंशी-कृष्ण और गौतम बुद्ध। कोई मानव-सहायक पात्र नहीं है, पर हर बिंब भूमि का एक पहलू दिखाता है — यही सहायक बिंब-समूह है।",
"c6_hin_cbse_01_006.md": "आसान शब्दों में: कविता का दिल एक ही बात है — भारत की स्तुति। एक ओर उसकी प्राकृतिक सुंदरता (हिमालय, नदियाँ, अमराइयाँ), दूसरी ओर आध्यात्मिक महिमा (राम, सीता, कृष्ण, बुद्ध की जन्मभूमि होना)। दोनों मिलकर कवि का देशभक्ति-भाव बनाते हैं — यही कविता का मुख्य विषय है।",
"c6_hin_cbse_01_007.md": "आसान शब्दों में: मुख्य स्तुति के साथ चार छोटे भाव भी चलते हैं — प्रकृति की निर्मल सुंदरता ('जगमग छटा निराली'), अनवरतता ('नित सिंधु झूमता' — हर दिन बहता रहना), आध्यात्मिक विरासत (राम-सीता-कृष्ण-बुद्ध) और शांति-करुणा ('जग को दया सिखाई')। मुख्य विषय जिस तरह डेरा डाले है, ये गौण विषय उसके साथी हैं।",
"c6_hin_cbse_01_008.md": "आसान शब्दों में: कविता पढ़कर आँखें बंद करो — आकाश चूमता हिमालय दिखेगा, नित झूमता सिंधु सुनाई देगा, झरते झरने और मस्त झाड़ियों की चहकती चिड़ियाँ दिखेंगी, घनी अमराइयों में कोयल पुकारेगी और बहती मलय पवन छू जाएगी। एक कविता में पाँचों इंद्रियों के चित्र — यही बिंब है।",
"c6_hin_cbse_01_009.md": "आसान शब्दों में: कवि ने कविता को स्वाद देने के लिए कई शब्द-चटनी की युक्तियाँ घोली हैं — बढ़ा-चढ़ाकर कहना ('आकाश चूमता हिमालय'), दोहराव ('वह ____ भूमि मेरी'), एक शब्द में दो अर्थ ('युद्ध-भूमि... बुद्ध-भूमि'), और निर्जीव को जीवन देना (सिंधु का 'झूमना')। यही अतिशयोक्ति, पुनरुक्ति, श्लेष और मानवीकरण हैं — कथा नहीं, कविता की अपनी युक्तियाँ।",
"c6_hin_cbse_01_010.md": "आसान शब्दों में: कविता के कठिन शब्द छोटे-छोटे खज़ाने हैं — सिंधु यानी महासागर, त्रिवेणी यानी तीन नदियों का संगम, छटा यानी चमक-शोभा, छहर यानी बिखरना, मसत यानी उल्लासित, अमराइयाँ यानी आम के बाग, मलय पवन यानी सुगंधित शीतल दक्षिण-हवा, रघुपति यानी श्रीराम, वंशी यानी बाँसुरी, अधर यानी होंठ, वसुंधरा यानी धरती। शब्द पकड़ो, पंक्ति खुद खुल जाएगी।",
"c6_hin_cbse_01_011.md": "आसान शब्दों में: यह कविता पढ़ी नहीं जाती, गाई जाती है। 'वह ____ भूमि मेरी' का बार-बार दोहराव उसे धुन देता है, और गति वाली क्रियाएँ — 'झूमता', 'लहर रही', 'चहक', 'झरते', 'बहती', 'सँवारती' — उसमें नाचती हैं। पुण्य-भूमि, स्वर्ण-भूमि, युद्ध-भूमि, बुद्ध-भूमि जैसे जुड़े शब्दों की माला लय को और मज़बूत करती है।",
"c6_hin_cbse_01_012.md": "आसान शब्दों में: इस नोड के तथ्य-सवाल पाठ में सीधे छिपे हैं — 'सिंधु' किसे कहते हैं (हिंद महासागर), कवि कौन है (सोहनलाल द्विवेदी), किसकी प्रशंसा है (भारत की), वंशी से किसने पुनीत गीत सुनाए (श्रीकृष्ण), और किसने जनम लेकर भूमि का यश बढ़ाया (गौतम बुद्ध)। जवाब याद नहीं करना — पंक्ति में खोजना है।",
"c6_hin_cbse_01_013.md": "आसान शब्दों में: कविता की ताकत यह है कि वह भूगोल — हिमालय, सिंधु, गंगा — को भावना (मातृभूमि) में ढाल देती है, और 'वह...मेरी' की आवृत्ति दावे को पक्का करती है। पर एक सीमा भी है: 'आकाश चूमना' जैसी अतिशयोक्ति और अत्यधिक आदर्शीकरण कुछ पाठकों को वास्तविकता से दूर लग सकते हैं। एक शक्ति और एक सीमा देखना ही आलोचना है।",
"c6_hin_cbse_01_014.md": "आसान शब्दों में: अब तुम्हारी बारी है। तीन काम सीखो — कविता की किसी पंक्ति का भावार्थ लिखना (पहले शब्द-अर्थ, फिर भाव), अपने क्षेत्र का वर्णन इसी शैली में करना (दोहराव और बिंब के साथ), और 'मेरी भूमि' पर ऐसा लघु-लेख लिखना जिसमें कविता की एक पंक्ति प्रमाण की तरह काम आए।",
"c6_hin_cbse_01_015.md": "आसान शब्दों में: कविता को लय पकड़कर वाचन करो, फिर पंक्तियों को भाव से जोड़ने का मिलान करो — 'अमराइयाँ घनी हैं' का जोड़ 'आम के घने उद्यान' से। सोचो और चर्चा करो: कोयल क्यों पुकार रही होगी? अनुमान लगाओ, कल्पना करो, और 'वंदे मातरम्' से तुलना करके देखो कि देश-प्रेम कितने रंगों में गाया जाता है।",
"c6_hin_cbse_02_001.md": "आसान शब्दों में: मेजर ध्यानचंद 'हॉकी का जादूगर' कहलाने वाले भारत के महानतम खिलाड़ी हैं, जिन्होंने 1936 के बर्लिन ओलंपिक में कप्तान के रूप में भारत को स्वर्ण पदक दिलाया। 'गोल' उनका आत्मकथात्मक संस्मरण है — यानी वे अपनी ही कहानी अपनी ही आवाज़ में सुनाते हैं, और शुरुआत 1933 की एक घटना से करते हैं।",
"c6_hin_cbse_02_002.md": "आसान शब्दों में: कथा के दो भाग हैं। पहला — 1933 का मैच, जहाँ प्रतिपक्षी ने सिर पर स्टिक मारी, ध्यानचंद पट्टी बाँधकर लौटे, 'बदला' की धमकी दी, छह गोल किए और अंत में पीठ थपथपाकर क्षमा कर दी। दूसरा — जीवन-कथा: 1905 में प्रयाग में जन्म, झाँसी, रेजिमेंट में हॉकी-निखार, और 1936 का ओलंपिक।",
"c6_hin_cbse_02_003.md": "आसान शब्दों में: यह कथा दो परिवेशों में घटती है। पहला — 1933 का सेना-हॉकी का मैदान (पंजाब रेजिमेंट बनाम सैंपर्स एंड माइनर्स), जहाँ धक्का-मुक्की स्वभाव का हिस्सा थी और खेल कठोर। दूसरा — ध्यानचंद का जीवन-परिवेश: 1905 का प्रयाग, झाँसी की छावनी, और अंत में बर्लिन का अंतरराष्ट्रीय मंच।",
"c6_hin_cbse_02_004.md": "आसान शब्दों में: ध्यानचंद का चरित्र उनके कर्मों में झलकता है — सिर पर चोट खाकर भी टूटे नहीं, गुस्से में 'बदला' कहा पर बदला छह गोलों के कौशल से लिया, और जीत के बाद प्रतिपक्षी की पीठ थपथपाकर क्षमा कर दी। जीवन में साधारण सिपाही से 'हॉकी का जादूगर' बने और गोल का श्रेय साथियों को देना नहीं भूले।",
"c6_hin_cbse_02_005.md": "आसान शब्दों में: नायक के आसपास के लोग उसे चमकाते हैं। प्रतिपक्षी खिलाड़ी पहले गुस्सैल है (स्टिक मारता है), फिर घबराता है और अंत में शर्मिंदा होता है; पंजाब रेजिमेंट की साथी टीम कौशल को मंच देती है; और मैदान का कठोर माहौल नायक के धैर्य की परीक्षा लेता है। हर सहायक पात्र ध्यानचंद का एक रंग उजागर करता है।",
"c6_hin_cbse_02_006.md": "आसान शब्दों में: कहानी का दिल एक ही वाक्य है — खेल-भावना जीत से ऊपर है। ध्यानचंद कहते हैं: 'मैंने तो अपना बदला ले ही लिया है... दोस्त, खेल में इतना गुस्सा अच्छा नहीं।' असली बदला गोलों का कौशल था, नफ़रत नहीं; और 'हार या जीत मेरी नहीं, देश की है'। प्रतिशोध की जगह कौशल और क्षमा — यही मुख्य विषय है।",
"c6_hin_cbse_02_007.md": "आसान शब्दों में: मुख्य संदेश के साथ चार छोटी सीखें भी चलती हैं — 1933 की सैन्य-संस्कृति जिसमें धक्का-मुक्की स्वाभाविक थी; मनोवैज्ञानिक युद्ध, जब 'बदला' की धमकी से प्रतिपक्षी घबरा गया; क्षमा की महिमा, जब वही खिलाड़ी शर्मिंदा हुआ; और निस्वार्थ टीम-भाव, जब गोल का श्रेय साथियों को बाँट दिया गया।",
"c6_hin_cbse_02_008.md": "आसान शब्दों में: संस्मरण को दृश्य बनाकर देखो — सिर पर उठी हॉकी स्टिक (चोट-दृश्य), पट्टी बाँधकर मैदान में लौटता खिलाड़ी (साहस), झटपट छह गोल (कौशल), पीठ थपथपाना (मैत्री) और साथी को दी जाती गेंद (टीम-भाव)। हर चित्र एक भाव बोलता है — दर्द, साहस, विजय, मैत्री — यही इस संस्मरण के बिंब हैं।",
"c6_hin_cbse_02_009.md": "आसान शब्दों में: इस कथा में उल्टी-फेर वाली बातें ही सच छुपाए बैठी हैं — जिसने 'बदला' का वादा किया, वही क्षमा करता है; जिसे चोट खाई (हानि), वही जीत का कारण बनती है; और प्रतिपक्षी का गुस्सा खुद उसे हरा देता है। 'बदला' शब्द वही रहता है, पर कर्म पूरी तरह बदल जाता है — उलटे परिणामों से सत्य निकलता है।",
"c6_hin_cbse_02_010.md": "आसान शब्दों में: कहानी के कठिन शब्द रोज़मर्रा के बोल से जुड़े हैं — धक्का-मुक्की यानी टकराव, नोंक-झोंक यानी बहस-टकराव, झटपट यानी तेज़ी से, रेजिमेंट यानी सेना की टुकड़ी, छावनी यानी सैनिक कैंप, नौसिखिया यानी अनुभवहीन नया खिलाड़ी, साधना यानी अभ्यास-परिश्रम, और श्रेय यानी कर्म का सम्मान-फल। संदर्भ पढ़ो, अर्थ खुद निकलेगा।",
"c6_hin_cbse_02_011.md": "आसान शब्दों में: ध्यानचंद 'मैं' कहकर लिखते हैं — 'मैं पंजाब रेजिमेंट की ओर से खेला करता था' — इसलिए हम घटना के भीतर खड़े होने जैसा महसूस करते हैं। सीधे संवाद ('तुम चिंता मत करो', 'दोस्त') और सैनिक शब्द (रेजिमेंट, छावनी, सूबेदार) शैली को सच्ची और अपनी बना देते हैं — यही सरल संस्मरण-शैली है।",
"c6_hin_cbse_02_012.md": "आसान शब्दों में: इस नोड के तथ्य-सवाल पाठ में सीधे मिलते हैं — मैच कौन-सा था (1933, पंजाब रेजिमेंट बनाम सैंपर्स एंड माइनर्स), चोट कहाँ लगी (सिर पर स्टिक से), कितने गोल किए (छह), जन्म कब-कहाँ हुआ (1905, प्रयाग), और 1936 में क्या हुआ (बर्लिन ओलंपिक स्वर्ण, कप्तान, 'हॉकी का जादूगर')। खोजो — उत्तर पाठ में ही हैं।",
"c6_hin_cbse_02_013.md": "आसान शब्दों में: कहानी पर सवाल उठाओ — क्या खेल में 'बदला' कभी उचित है? क्या प्रतिपक्षी की गलती माफ़ी योग्य थी? कथा की ताकत है कि वह 'बदला' को कौशल और क्षमा में बदल देती है; सीमा यह कि धमकी देकर मनोयुद्ध जीतना कुछ पाठकों को 'छल' जैसा लग सकता है। अच्छा भी देखो, सवाल भी उठाओ — यही मूल्यांकन है।",
"c6_hin_cbse_02_014.md": "आसान शब्दों में: अब लेखक बनो — खेल के मैदान की कोई सच्ची घटना संस्मरण-शैली में लिखो, या इस कथा का अंत आगे बढ़ाओ (प्रतिपक्षी को क्या लगा होगा?), या 'मेरा खेल-अनुभव' पर ऐसा लेख लिखो जिसमें खेल-भावना का प्रमाण साफ़ दिखे। शैली वही रखो जो पाठ में है — 'मैं' की आवाज़।",
"c6_hin_cbse_02_015.md": "आसान शब्दों में: अंत में बहस करो — 'क्या खेल में बदला उचित है?' पर समूह में पक्ष-विपक्ष रखो, 'क्षमा बनाम प्रतिशोध' पर अपना मत बोलो, और सोचो कि 'खेल-भावना आज भी ज़रूरी है?' राय प्रमाण से दो, दूसरे की बात सम्मान से सुनो — यही चर्चा के नियम हैं। 'हार की जीत' जैसे शीर्षक को दोनों पात्रों पर आज़माओ।",
"c6_hin_cbse_03_001.md": "आसान शब्दों में: गोपालकृष्ण कौल (1923–2007) बाल-साहित्य के प्रेमी कवि हैं, जिन्होंने देश-प्रेम, प्रकृति और जीव-जंतुओं पर मनोरम कविताएँ लिखीं — 'देश हमें देता है सब कुछ, हम भी तो कुछ देना सीखें' उन्हीं की पंक्ति है। 'पहली बूँद' में उन्होंने वर्षा के पहले दिन का पूरा जीवंत चित्र खींच दिया है।",
"c6_hin_cbse_03_002.md": "आसान शब्दों में: कविता के चार छंद-खंड हैं, और हर खंड के अंत में वही धुन — 'पहली बूँद धरा पर आई'। पहले खंड में अंकुर फूटता है और नव-जीवन अँगड़ाई लेता है; दूसरे में आसमान में उड़ता सागर (बादल) बिजलियों और नगाड़ों के साथ आता है; तीसरे में धरती की चिर-प्यास बुझती है; चौथे में बूढ़ी धरती शस्य-श्यामला बनने को ललचाती है।",
"c6_hin_cbse_03_003.md": "आसान शब्दों में: कविता का मंच दो तरफ़ बँटा है — ऊपर आकाश, जहाँ बादलों का सागर उड़ता है, स्वर्णिम बिजलियाँ चमकती हैं और गड़गड़ाहट नगाड़ों-सी बजती है; और नीचे धरती, जहाँ सूखी ज़मीन पर पहली बूँद गिरते ही अंकुर फूट पड़ता है और दूब पुलकी-मुसकाई होती है। वर्षा दोनों दुनिया को एक धागे में पिरो देती है।",
"c6_hin_cbse_03_004.md": "आसान शब्दों में: इस कविता का मुख्य 'पात्र' कोई इंसान नहीं — धरती (वसुंधरा) है। वह 'बूढ़ी' कहलाती है पर शस्य-श्यामला बनने को ललचाती है; उसके 'सूखे अधर' (होंठ) प्यासे हैं; दूब उसकी 'रोमावलि-सी' (रोम-पंक्ति) है; और बूँद के अमृत से उसकी 'चिर-प्यास' बुझ जाती है। कवि ने धरती को जीता-जागता इंसान बना दिया है।",
"c6_hin_cbse_03_005.md": "आसान शब्दों में: धरती के इर्द-गिर्द हर तत्व अपना काम करता है — पहली बूँद 'अमृत-सी' जीवन-दान देती है, अंकुर नया जीवन उगलता है, दूब वसुंधरा की 'रोमावलि-सी' मुसकान है, बादल 'उड़ता सागर' और 'जलधर' बनकर पानी उतारता है, बिजली 'स्वर्णिम' चमक बिखेरती है, और नगाड़े गड़गड़ाहट का उत्सव हैं — सब मिलकर वर्षा का जीवंत संसार बनाते हैं।",
"c6_hin_cbse_03_006.md": "आसान शब्दों में: कविता का दिल यह है कि एक बूँद पूरा जीवन-चक्र चालू कर देती है — 'अंकुर फूट पड़ा', 'नव-जीवन की ले अँगड़ाई', 'धरती की चिर-प्यास बुझाई', और 'बूढ़ी धरती शस्य-श्यामला बनने को फिर से ललचाई'। वर्षा का यह नव-जीवन-दान और प्रकृति की करुणा — यही कविता का मुख्य विषय है।",
"c6_hin_cbse_03_007.md": "आसान शब्दों में: मुख्य विषय के साथ चार साथी भाव चलते हैं — प्रकृति की करुणा ('करुणा-विगलित अश्रु' यानी बादल के आँसू), जीवन-चक्र और पुनरुत्थान (बूढ़ी धरती का फिर हरा होना), प्रकृति का उत्सव (नगाड़े और बिजली), और निःशुष्कता से समृद्धि का सफ़र (सूखे अधर से शस्य-श्यामला तक)। ये गौण विषय मुख्य भाव को चारों ओर से सहारा देते हैं।",
"c6_hin_cbse_03_008.md": "आसान शब्दों में: कविता इंद्रियों का पूरा उत्सव है — आँखों के लिए 'आसमान में उड़ता सागर' और 'स्वर्णिम पर' बिजली; कानों के लिए बजते नगाड़े; छुअन के लिए धरती के सूखे अधर; सुंदरता के लिए 'हरी दूब पुलकी-मुसकाई'। और अंबर को 'नीले नयनों-सा', जलधर को 'काली पुतली-से' दिखाना — मानवीकृत दृश्य-चित्रण की चोटी है।",
"c6_hin_cbse_03_009.md": "आसान शब्दों में: कवि की सजावट-युक्तियाँ पहचानो — रूपक में बादल सीधे 'उड़ता सागर' और 'जलधर' बन जाता है; उपमा में '-सी/-सा' की चटनी है ('अमृत-सी', 'रोमावलि-सी', 'नीले नयनों-सा'); मानवीकरण में धरती 'ललचाती' है; 'चिर-प्यास' श्लेष है; और हर छंद में 'पहली बूँद' का लौट आना यमक है। '-सी' देखो, उपमा समझो।",
"c6_hin_cbse_03_010.md": "आसान शब्दों में: कविता के शब्द टुकड़ों में तोड़ो तो सब सरल हैं — पावस यानी वर्षा, अंकुर यानी नया पौधा, अँगड़ाई यानी शरीर फैलाना, अधर यानी होंठ, वसुंधरा यानी धरती, रोमावलि यानी रोम-पंक्ति, पुलकी यानी गदगद, जलधर यानी बादल, अंबर यानी आकाश, चिर यानी बहुत समय, शस्य-श्यामला यानी फसलों से हरी-भरी, तरुणाई यानी युवावस्था। शब्द पक्के, तो भाव अपने आप खुलता है।",
"c6_hin_cbse_03_011.md": "आसान शब्दों में: यह कविता संस्कृत-मिश्रित मधुर हिंदी में बजा हुआ संगीत है — चार-पंक्ति के छंद-खंड, हर खंड के अंत में 'पहली बूँद धरा पर आई' की आवृत्ति, '-सी/-सा' उपमा-सूचक की चटनी, और 'नगाड़े', 'पुलकी-मुसकाई' जैसे ध्वनि-प्रभाव वाले शब्द। छंद, लय, दोहराव और ध्वनि — चारों मिलकर कविता को गाने-जैसा बना देते हैं।",
"c6_hin_cbse_03_012.md": "आसान शब्दों में: तथ्य-सवालों के उत्तर पाठ में सीधे लिखे हैं — कवि कौन (गोपालकृष्ण कौल), 'पावस' का अर्थ (वर्षा), 'अंकुर' का अर्थ (नया पौधा), 'अधर' का अर्थ (होंठ), 'जलधर' का अर्थ (बादल), हर छंद में क्या दोहराया जाता है ('पहली बूँद धरा पर आई'), और 'बूढ़ी धरती शस्य-श्यामला' का अर्थ (वृद्ध धरती का हरी-भरी होना)। याद नहीं — खोजना है।",
"c6_hin_cbse_03_013.md": "आसान शब्दों में: कविता की ताकत — वह एक बूँद को 'अमृत-सी' जीवन-दान बनाकर धरती को जीवंत पात्र बना देती है और 'पहली बूँद' का दोहराव पूरी कविता का भाव-केंद्र बन जाता है। सीमा — अत्यधिक मानवीकरण कुछ पाठकों को अतिरंजित लग सकता है, और कविता में केवल सुंदरता है, कोई संघर्ष नहीं। दोनों पक्ष देखो — यही आलोचना है।",
"c6_hin_cbse_03_014.md": "आसान शब्दों में: अब खुद लिखो — पहले कविता की किसी पंक्ति का भावार्थ (शब्द-अर्थ + भाव), फिर अपने क्षेत्र की वर्षा का वर्णन इसी कविता की शैली में ('-सी' उपमा और बिंब के साथ), या 'पहली बूँद' के अपने अनुभव पर ऐसा लघु-लेख जिसमें कविता की एक पंक्ति प्रमाण बनकर आए।",
"c6_hin_cbse_03_015.md": "आसान शब्दों में: आख़िर में कविता को ताल में वाचन करो, पंक्तियों को भाव से मिलाओ ('पहली बूँद' ↔ 'जीवन-दान'), और फिर बहस छेड़ो — धरती की प्यास 'चिर-प्यास' क्यों है? बूढ़ी धरती क्यों ललचाई? 'पहली बूँद' पानी है या जीवन-दान? अपनी राय प्रमाण से दो — चर्चा यहीं से शुरू होती है।",
}
